"use client"

import { useState, useEffect, useContext, useRef } from "react"
import { useNavigate } from "react-router-dom"
import { AuthContext } from "../../context/AuthContext"
import api from "../../services/api"
import Header from "../../components/common/Header"
import Footer from "../../components/common/Footer"
import { User, MapPin, Phone, Mail, Camera, Save, Loader } from "lucide-react"
import toast from "react-hot-toast"

const ProviderProfile = () => {
  const { currentUser, setCurrentUser } = useContext(AuthContext)
  const navigate = useNavigate()
  const fileInputRef = useRef(null)

  const [formData, setFormData] = useState({
    mess_name: "",
    owner_name: "",
    mobile_no: "",
    address: "",
  })
  const [profileImage, setProfileImage] = useState(null)
  const [previewImage, setPreviewImage] = useState("")
  const [isLoading, setIsLoading] = useState(true)
  const [isSubmitting, setIsSubmitting] = useState(false)

  useEffect(() => {
    const fetchProviderProfile = async () => {
      try {
        const { data } = await api.get("/provider/profile")

        setFormData({
          mess_name: data.mess_name || "",
          owner_name: data.owner_name || "",
          mobile_no: data.mobile_no || "",
          address: data.address || "",
        })

        if (data.profile_image) {
          setPreviewImage(data.profile_image)
        }
      } catch (error) {
        console.error("Error fetching provider profile:", error)
        toast.error("Failed to load profile data")
      } finally {
        setIsLoading(false)
      }
    }

    if (currentUser) {
      fetchProviderProfile()
    } else {
      setIsLoading(false)
    }
  }, [currentUser])

  const handleChange = (e) => {
    const { name, value } = e.target
    setFormData({
      ...formData,
      [name]: value,
    })
  }

  const handleFileChange = (e) => {
    const file = e.target.files[0]
    if (file) {
      setProfileImage(file)

      // Create preview URL
      const reader = new FileReader()
      reader.onloadend = () => {
        setPreviewImage(reader.result)
      }
      reader.readAsDataURL(file)
    }
  }

  const triggerFileInput = () => {
    fileInputRef.current.click()
  }

  const handleSubmit = async (e) => {
    e.preventDefault()
    setIsSubmitting(true)

    try {
      // Create FormData object for file upload
      const profileFormData = new FormData()
      profileFormData.append("mess_name", formData.mess_name)
      profileFormData.append("owner_name", formData.owner_name)
      profileFormData.append("mobile_no", formData.mobile_no)
      profileFormData.append("address", formData.address)

      // Only append profile_image if it exists
      if (profileImage) {
        profileFormData.append("profile_image", profileImage)
      }

      const { data } = await api.post("/provider/profile", profileFormData, {
        headers: {
          "Content-Type": "multipart/form-data",
        },
      })

      // Update current user in context
      setCurrentUser({
        ...currentUser,
        mess_name: data.provider.mess_name,
        owner_name: data.provider.owner_name,
        mobile_no: data.provider.mobile_no,
        address: data.provider.address,
        profile_image: data.provider.profile_image,
      })

      toast.success("Profile updated successfully")
    } catch (error) {
      console.error("Error updating profile:", error)
      toast.error("Failed to update profile. Please try again.")
    } finally {
      setIsSubmitting(false)
    }
  }

  if (isLoading) {
    return (
      <div className="flex flex-col min-h-screen">
        <Header />
        <main className="flex-grow py-10 bg-gray-50">
          <div className="container mx-auto px-4">
            <div className="flex justify-center items-center h-64">
              <div className="animate-spin rounded-full h-16 w-16 border-t-2 border-b-2 border-orange-500"></div>
            </div>
          </div>
        </main>
        <Footer />
      </div>
    )
  }

  return (
    <div className="flex flex-col min-h-screen">
      <Header />

      <main className="flex-grow py-10 bg-gray-50">
        <div className="container mx-auto px-4">
          <div className="max-w-3xl mx-auto">
            <div className="bg-white rounded-lg shadow-md overflow-hidden">
              <div className="bg-orange-500 text-white py-4 px-6">
                <h2 className="text-2xl font-bold">Provider Profile</h2>
                <p className="text-sm">Update your tiffin service information</p>
              </div>

              <form onSubmit={handleSubmit} className="p-6">
                {/* Profile Image */}
                <div className="flex flex-col items-center mb-8">
                  <div
                    className="relative w-32 h-32 rounded-full overflow-hidden border-4 border-orange-500 cursor-pointer mb-2"
                    onClick={triggerFileInput}
                  >
                    {previewImage ? (
                      <img
                        src={previewImage || "/placeholder.svg"}
                        alt="Profile"
                        className="w-full h-full object-cover"
                      />
                    ) : (
                      <div className="w-full h-full bg-gray-200 flex items-center justify-center">
                        <User className="h-16 w-16 text-gray-400" />
                      </div>
                    )}
                    <div className="absolute bottom-0 right-0 bg-orange-500 p-2 rounded-full">
                      <Camera className="h-4 w-4 text-white" />
                    </div>
                  </div>
                  <input
                    type="file"
                    ref={fileInputRef}
                    onChange={handleFileChange}
                    accept="image/*"
                    className="hidden"
                  />
                  <p className="text-sm text-gray-500">Click to change profile image</p>
                </div>

                <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                  {/* Mess Name */}
                  <div>
                    <label htmlFor="mess_name" className="block text-sm font-medium text-gray-700 mb-1">
                      Mess/Business Name
                    </label>
                    <div className="relative">
                      <input
                        type="text"
                        id="mess_name"
                        name="mess_name"
                        value={formData.mess_name}
                        onChange={handleChange}
                        className="input-field pl-10"
                        placeholder="Enter your mess or business name"
                        required
                      />
                      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <User className="h-5 w-5 text-gray-400" />
                      </div>
                    </div>
                  </div>

                  {/* Owner Name */}
                  <div>
                    <label htmlFor="owner_name" className="block text-sm font-medium text-gray-700 mb-1">
                      Owner Name
                    </label>
                    <div className="relative">
                      <input
                        type="text"
                        id="owner_name"
                        name="owner_name"
                        value={formData.owner_name}
                        onChange={handleChange}
                        className="input-field pl-10"
                        placeholder="Enter owner's full name"
                        required
                      />
                      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <User className="h-5 w-5 text-gray-400" />
                      </div>
                    </div>
                  </div>

                  {/* Email (Read-only) */}
                  <div>
                    <label htmlFor="email" className="block text-sm font-medium text-gray-700 mb-1">
                      Email Address
                    </label>
                    <div className="relative">
                      <input
                        type="email"
                        id="email"
                        value={currentUser?.email || ""}
                        className="input-field pl-10 bg-gray-100"
                        readOnly
                      />
                      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Mail className="h-5 w-5 text-gray-400" />
                      </div>
                    </div>
                    <p className="text-xs text-gray-500 mt-1">Email cannot be changed</p>
                  </div>

                  {/* Mobile Number */}
                  <div>
                    <label htmlFor="mobile_no" className="block text-sm font-medium text-gray-700 mb-1">
                      Mobile Number
                    </label>
                    <div className="relative">
                      <input
                        type="text"
                        id="mobile_no"
                        name="mobile_no"
                        value={formData.mobile_no}
                        onChange={handleChange}
                        className="input-field pl-10"
                        placeholder="Enter your 10-digit mobile number"
                        required
                      />
                      <div className="absolute inset-y-0 left-0 pl-3 flex items-center pointer-events-none">
                        <Phone className="h-5 w-5 text-gray-400" />
                      </div>
                    </div>
                  </div>
                </div>

                {/* Address */}
                <div className="mt-6">
                  <label htmlFor="address" className="block text-sm font-medium text-gray-700 mb-1">
                    Business Address
                  </label>
                  <div className="relative">
                    <textarea
                      id="address"
                      name="address"
                      value={formData.address}
                      onChange={handleChange}
                      className="input-field pl-10"
                      placeholder="Enter your business address"
                      rows="3"
                      required
                    ></textarea>
                    <div className="absolute top-3 left-0 pl-3 flex items-start pointer-events-none">
                      <MapPin className="h-5 w-5 text-gray-400" />
                    </div>
                  </div>
                </div>

                {/* Submit Button */}
                <div className="mt-8">
                  <button
                    type="submit"
                    className="btn-primary w-full flex items-center justify-center"
                    disabled={isSubmitting}
                  >
                    {isSubmitting ? (
                      <>
                        <Loader className="h-4 w-4 mr-2 animate-spin" />
                        Updating...
                      </>
                    ) : (
                      <>
                        <Save className="h-4 w-4 mr-2" />
                        Save Changes
                      </>
                    )}
                  </button>
                </div>
              </form>
            </div>
          </div>
        </div>
      </main>

      <Footer />
    </div>
  )
}

export default ProviderProfile
